begin;
select plan(13);
select ok(not has_table_privilege('authenticated','public.books_native_invoice_postings','select'),'native source receipts remain private');
select ok(not has_table_privilege('anon','public.books_native_invoice_postings','insert'),'anonymous cannot create native money');
select ok(has_table_privilege('service_role','public.books_native_invoice_postings','select,insert'),'server can inspect and append authorized receipts');
select ok(not has_table_privilege('service_role','public.books_native_invoice_postings','update,delete'),'server cannot edit native receipt history');
select ok((select relrowsecurity from pg_class where oid='public.books_native_invoice_postings'::regclass),'native source receipts retain RLS');
select ok(not has_function_privilege('authenticated','public.post_books_native_invoice(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,text)','execute'),'browser cannot invoke native monetary writer');
select ok(not has_function_privilege('anon','public.read_books_native_invoice_posting(uuid,uuid,uuid,uuid,uuid)','execute'),'anonymous cannot inspect native monetary receipts');
select ok(has_function_privilege('service_role','public.post_books_native_invoice(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,text)','execute'),'authorized server can invoke explicitly scoped writer');
select ok(not (select prosecdef from pg_proc where oid='public.post_books_native_invoice(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,text)'::regprocedure),'financial writer retains invoker authority');
select ok(not has_function_privilege('authenticated','arc_private.books_native_economic_fence()','execute'),'private source coordinator cannot be called directly');
select ok(exists(select 1 from pg_constraint where conrelid='public.books_native_journal_entries'::regclass and conname='books_native_journal_origin'),'one shared native journal requires an exclusive source or adjustment origin');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_native_invoice_postings'::regclass and tgname='books_native_invoice_receipt_complete' and tgdeferrable and tginitdeferred),'source receipt requires complete journal at commit');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_native_journal_entries'::regclass and tgname='books_native_invoice_journal_complete' and tgdeferrable and tginitdeferred),'operational journal requires complete original source receipt at commit');
select * from finish();
rollback;
